import type { RequestHandler } from './$types';
import { db, flights, weatherData, airportDaylight, flightTimes, guernseyTodayStr, guernseyTomorrowStr } from '$lib/server/db';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import { and, gte, lte, inArray, or, eq, asc } from 'drizzle-orm';

const FLIGHT_COLUMNS = {
  id: flights.id,
  flightNumber: flights.flightNumber,
  departureAirport: flights.departureAirport,
  arrivalAirport: flights.arrivalAirport,
  scheduledDeparture: flights.scheduledDeparture,
  scheduledArrival: flights.scheduledArrival,
  actualDeparture: flights.actualDeparture,
  actualArrival: flights.actualArrival,
  status: flights.status,
  canceled: flights.canceled,
  aircraftType: flights.aircraftType,
  delayMinutes: flights.delayMinutes,
  flightDate: flights.flightDate,
};

/**
 * Mirrors the homepage load function's data — flight list, weather, daylight for a given date.
 * Query params: date (YYYY-MM-DD, defaults to today Guernsey time)
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const now = new Date();
    const todayStr = guernseyTodayStr(now);
    const tomorrowStr = guernseyTomorrowStr(now);

    const dateParam = url.searchParams.get('date');
    const displayDateStr = dateParam && (dateParam === todayStr || dateParam === tomorrowStr)
      ? dateParam
      : todayStr;

    const displayFlights = await db
      .select(FLIGHT_COLUMNS)
      .from(flights)
      .where(eq(flights.flightDate, displayDateStr))
      .orderBy(flights.scheduledDeparture);

    const flightIds = displayFlights.map(f => f.id);
    const airportCodes = [...new Set(
      displayFlights.flatMap(f => [f.departureAirport, f.arrivalAirport])
    )];

    const weatherStartDate = new Date(displayDateStr + 'T00:00:00Z');
    const weatherEndDate = new Date(weatherStartDate);
    weatherEndDate.setUTCDate(weatherEndDate.getUTCDate() + 2);

    const [estimatedTimesRows, weatherRows, daylightRows] = await Promise.all([
      flightIds.length > 0
        ? db.select({ flightId: flightTimes.flightId, timeType: flightTimes.timeType, timeValue: flightTimes.timeValue })
            .from(flightTimes)
            .where(and(
              inArray(flightTimes.flightId, flightIds),
              inArray(flightTimes.timeType, ['EstimatedBlockOff', 'EstimatedBlockOn']),
            ))
        : Promise.resolve([]),
      airportCodes.length > 0
        ? db.select({
            airportCode: weatherData.airportCode, timestamp: weatherData.timestamp,
            temperature: weatherData.temperature, windSpeed: weatherData.windSpeed,
            windDirection: weatherData.windDirection, weatherCode: weatherData.weatherCode,
          })
          .from(weatherData)
          .where(and(
            inArray(weatherData.airportCode, airportCodes),
            gte(weatherData.timestamp, weatherStartDate),
            lte(weatherData.timestamp, weatherEndDate),
          ))
          .orderBy(weatherData.timestamp)
        : Promise.resolve([]),
      airportCodes.length > 0
        ? db.select({
            airportCode: airportDaylight.airportCode, date: airportDaylight.date,
            sunrise: airportDaylight.sunrise, sunset: airportDaylight.sunset,
          })
          .from(airportDaylight)
          .where(and(
            inArray(airportDaylight.airportCode, airportCodes),
            or(eq(airportDaylight.date, todayStr), eq(airportDaylight.date, tomorrowStr)),
          ))
          .orderBy(asc(airportDaylight.date))
        : Promise.resolve([]),
    ]);

    // Build estimated times map
    const estimatedTimesMap = new Map<number, { estimatedDeparture?: string; estimatedArrival?: string }>();
    for (const t of estimatedTimesRows) {
      const existing = estimatedTimesMap.get(t.flightId) ?? {};
      if (t.timeType === 'EstimatedBlockOff') existing.estimatedDeparture = t.timeValue.toISOString();
      else if (t.timeType === 'EstimatedBlockOn') existing.estimatedArrival = t.timeValue.toISOString();
      estimatedTimesMap.set(t.flightId, existing);
    }

    const flightsForDisplay = displayFlights
      .map(f => ({
        ...f,
        estimatedDeparture: estimatedTimesMap.get(f.id)?.estimatedDeparture ?? null,
        estimatedArrival: estimatedTimesMap.get(f.id)?.estimatedArrival ?? null,
      }))
      .sort((a, b) => {
        const aTime = new Date(a.estimatedDeparture ?? a.scheduledDeparture).getTime();
        const bTime = new Date(b.estimatedDeparture ?? b.scheduledDeparture).getTime();
        return aTime - bTime;
      });

    // Build weather map
    const weatherMap: Record<string, typeof weatherRows> = {};
    for (const row of weatherRows) {
      if (!weatherMap[row.airportCode]) weatherMap[row.airportCode] = [];
      weatherMap[row.airportCode].push(row);
    }

    // Build daylight map
    const daylightMap: Record<string, typeof daylightRows> = {};
    for (const row of daylightRows) {
      if (!daylightMap[row.airportCode]) daylightMap[row.airportCode] = [];
      daylightMap[row.airportCode].push(row);
    }

    const data = {
      flights: flightsForDisplay,
      weatherMap,
      daylightMap,
      displayDate: displayDateStr,
      todayStr,
      tomorrowStr,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/homepage]', err);
    return debugError('Query failed', 500);
  }
};

import type { RequestHandler } from './$types';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import {
  getFilterOptions,
  getHeroStats,
  getDelayDistribution,
  getDayOfWeekDistribution,
  getHourDistribution,
  getBusiestDays,
  getWorstDays,
  getRouteStats,
  getFlightNumberStats,
  getAircraftStats,
  getTopDelays,
  getDailyOtpStats,
  getMonthlyBreakdown,
  getWindDelayStats,
  getVisibilityDelayStats,
  getPrecipitationDelayStats,
  getWeatherCodeDelayStats,
  getCrosswindDelayStats,
  getWorstWeatherDays,
  getDelayImpact,
  getWorstDelayDays,
} from '../../../../stats/lib/queries';
import type { FilterConfig } from '../../../../stats/lib/types';

/**
 * Mirrors the stats page load function — reuses all existing query functions.
 * Query params: range, dateFrom, dateTo, airline, route, direction, dow, season, month, year, threshold
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const range = url.searchParams.get('range') ?? '90';
    const dateFrom = url.searchParams.get('dateFrom') ?? '';
    const dateTo = url.searchParams.get('dateTo') ?? '';
    const activeAirline = url.searchParams.get('airline') ?? '';
    const activeRoutes = url.searchParams.getAll('route').filter(Boolean);
    const activeDirection = url.searchParams.get('direction') ?? '';
    const activeDow = url.searchParams.get('dow') ?? '';
    const activeSeason = url.searchParams.get('season') ?? '';
    const activeMonth = url.searchParams.get('month') ?? '';
    const activeYear = url.searchParams.get('year') ?? '';
    const thresholdParam = parseInt(url.searchParams.get('threshold') ?? '15', 10);
    const threshold = [0, 15, 30].includes(thresholdParam) ? thresholdParam : 15;
    const minFlightsPerRoute = range === '30' ? 2 : range === '90' ? 3 : 5;

    const parsedRoutes = activeRoutes.map(r => {
      const parts = r.split('-');
      const dep = parts[0] ?? '';
      const arr = parts.slice(1).join('-');
      return { dep, arr, key: r };
    }).filter(r => r.dep && r.arr);

    const dowNum = parseInt(activeDow, 10);
    const monthNum = parseInt(activeMonth, 10);
    const yearNum = parseInt(activeYear, 10);

    const filterConfig: FilterConfig = {
      range: {
        type: range as '30' | '90' | 'custom' | 'all',
        dateFrom: dateFrom || undefined,
        dateTo: dateTo || undefined,
      },
      airline: activeAirline || undefined,
      routes: parsedRoutes.length > 0 ? parsedRoutes : undefined,
      direction: activeDirection as 'dep' | 'arr' | '' || undefined,
      dow: activeDow !== '' && !isNaN(dowNum) && dowNum >= 0 && dowNum <= 6 ? dowNum : undefined,
      season: activeSeason as 'summer' | 'winter' | 'spring' | 'autumn' | '' || undefined,
      month: activeMonth !== '' && !isNaN(monthNum) && monthNum >= 1 && monthNum <= 12 ? monthNum : undefined,
      year: activeYear !== '' && !isNaN(yearNum) && yearNum >= 2000 && yearNum <= 2100 ? yearNum : undefined,
      threshold,
      minFlightsPerRoute,
    };

    const [
      filterOptions,
      heroStats,
      delayDistribution,
      dayOfWeek,
      departureHour,
      busiestDays,
      worstDays,
      worstRoutes,
      flightNumbers,
      aircraftUsage,
      topDelays,
      dailyOtp,
      monthlyBreakdown,
      windDelays,
      visibilityDelays,
      precipDelays,
      weatherCodeDelays,
      crosswindDelays,
      worstWeatherDays,
      delayImpact,
      worstDelayDays,
    ] = await Promise.all([
      getFilterOptions(),
      getHeroStats(filterConfig),
      getDelayDistribution(filterConfig),
      getDayOfWeekDistribution(filterConfig),
      getHourDistribution(filterConfig),
      getBusiestDays(filterConfig, 10),
      getWorstDays(filterConfig, 10),
      getRouteStats(filterConfig),
      getFlightNumberStats(filterConfig, 20),
      getAircraftStats(filterConfig),
      getTopDelays(filterConfig, 10),
      getDailyOtpStats(filterConfig),
      getMonthlyBreakdown(filterConfig),
      getWindDelayStats(filterConfig),
      getVisibilityDelayStats(filterConfig),
      getPrecipitationDelayStats(filterConfig),
      getWeatherCodeDelayStats(filterConfig),
      getCrosswindDelayStats(filterConfig),
      getWorstWeatherDays(filterConfig, 10),
      getDelayImpact(filterConfig),
      getWorstDelayDays(filterConfig, 10),
    ]);

    const data = {
      filterConfig,
      filterOptions,
      heroStats,
      delayDistribution,
      dayOfWeek,
      departureHour,
      busiestDays,
      worstDays,
      worstRoutes,
      flightNumbers,
      aircraftUsage,
      topDelays,
      dailyOtp,
      monthlyBreakdown,
      windDelays,
      visibilityDelays,
      precipDelays,
      weatherCodeDelays,
      crosswindDelays,
      worstWeatherDays,
      delayImpact,
      worstDelayDays,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/stats]', err);
    return debugError('Query failed', 500);
  }
};

